<div class="d-flex justify-content-between"><div><h3>Catálogo contable</h3><p class="text-muted"><?=e($emp['rfc'].' - '.$emp['razon_social'])?></p></div><a href="contabilidad.php?id_empresa=<?=$id?>" class="btn btn-outline-secondary align-self-start">Regresar</a></div>
<div class="sat-card p-4 mb-4"><h5>Nueva cuenta</h5><form class="row g-2" method="post" action="php/postGuardarCuenta.php"><input type="hidden" name="id_empresa" value="<?=$id?>"><div class="col-md-2"><input class="form-control" name="numero_cuenta" placeholder="Número" required></div><div class="col-md-4"><input class="form-control" name="nombre" placeholder="Nombre de cuenta" required></div><div class="col-md-3"><select class="form-control" name="codigo_agrupador"><option value="">Código agrupador SAT</option><?php while($a=mysqli_fetch_assoc($agr)):?><option value="<?=e($a['codigo'])?>"><?=e($a['codigo'].' - '.$a['nombre'])?></option><?php endwhile?></select></div><div class="col-md-1"><select class="form-control" name="naturaleza"><option>D</option><option>A</option></select></div><div class="col-md-2"><select class="form-control" name="tipo_cuenta"><option>ACTIVO</option><option>PASIVO</option><option>CAPITAL</option><option>INGRESO</option><option>COSTO</option><option>GASTO</option><option>ORDEN</option></select></div><div class="col-12"><button class="btn btn-primary">Guardar cuenta</button></div></form></div>
<div class="sat-card p-4"><table class="sat-tabla"><thead><tr><th>Cuenta</th><th>Nombre</th><th>Agrupador SAT</th><th>Naturaleza</th><th>Tipo</th></tr></thead><tbody><?php while($c=mysqli_fetch_assoc($cts)):?><tr><td><?=e($c['numero_cuenta'])?></td><td><?=e($c['nombre'])?></td><td><?=e($c['codigo_agrupador'].' '.$c['agrupador'])?></td><td><?=e($c['naturaleza'])?></td><td><?=e($c['tipo_cuenta'])?></td></tr><?php endwhile?></tbody></table></div><?php sat_page_fin(); include('../assets/footer.php');?>
